.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 13px;
  border-radius: 7px;
  background: var(--raised, #222428);
  color: var(--ink, #f2f2ef);
  padding: 13px 19px;
  font-size: 13px;
  font-weight: 550;
  min-height: 46px;
  transition: background 0.15s;
}
.ds-button:hover {
  background: #303339;
}
.ds-button-light {
  background: var(--accent, #d9e6a3);
  color: #202417;
}
.ds-button-light:hover {
  background: #e6efc5;
}
.ds-button{font-family:var(--font, "DM Sans Variable", sans-serif);line-height:1.6;border:0;text-decoration:none;cursor:pointer;}.ds-button:disabled{opacity:.5;cursor:not-allowed;}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent, #d9e6a3);outline-offset:5px;}
@media(prefers-reduced-motion:reduce){.ds-button{transition:none}}

