.ds-search-field {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: 1;
  min-width: 160px;
  padding: 0 16px;
  background: var(--surface, #191b1e);
  border: 1px solid #727983;
  border-radius: 8px;
}
.ds-search-field > svg {
  color: #999fa8;
}
.ds-search-field:focus-within {
  border-color: var(--accent, #d9e6a3);
  outline: 1px solid var(--accent, #d9e6a3);
}
.ds-search-field input {
  height: 51px;
  width: 100%;
  min-width: 0;
  background: transparent;
  border: 0;
  outline: 0;
  font-size: 13px;
}
.ds-search-field input:focus-visible {
  outline: none;
}
.ds-search-field input::placeholder {
  color: #9aa0aa;
  opacity: 1;
}
.ds-search-field kbd {
  border: 1px solid #454a53;
  border-radius: 4px;
  color: #b1b7c0;
  font-size: 11px;
  padding: 0 7px;
}
.ds-search-field{font-family:var(--font, "DM Sans Variable", sans-serif);line-height:1.6;color:var(--ink, #f2f2ef);}.ds-search-field input{font:inherit;color:inherit;caret-color:var(--accent, #d9e6a3);}.ds-search-field svg{flex-shrink:0;}.ds-search-field input{font-size:13px;}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent, #d9e6a3);outline-offset:5px;}
.ds-search-field input:focus-visible{outline:none;}

.ds-category-nav {
  display: flex;
  gap: 8px;
  align-items: center;
  overflow-x: auto;
  padding: 0 0 22px;
  scrollbar-width: thin;
}
.ds-category-nav > a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 13px;
  border: 1px solid #35383e;
  border-radius: 7px;
  white-space: nowrap;
  color: #b8bdc4;
  font-size: 12px;
  min-height: 39px;
}
.ds-category-nav > a:hover {
  border-color: #60666f;
  color: var(--ink, #f2f2ef);
}
.ds-category-nav > a.ds-selected {
  background: var(--ink, #f2f2ef);
  color: #1b1e23;
  border-color: var(--ink, #f2f2ef);
}
.ds-category-nav > a > span {
  font-size: 10px;
  opacity: 0.7;
  font-variant-numeric: tabular-nums;
}
.ds-category-nav{font-family:var(--font, "DM Sans Variable", sans-serif);line-height:1.6;}.ds-category-nav a{text-decoration:none;}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent, #d9e6a3);outline-offset:5px;}

.ds-tag {
  display: inline-flex;
  font-size: 10px;
  color: #bbc3cf;
  background: #24272c;
  border-radius: 4px;
  padding: 4px 8px;
  max-width: 55%;
  overflow-wrap: anywhere;
}
.ds-tag:hover {
  background: #353b44;
  color: var(--ink, #f2f2ef);
}
.ds-tag{font-family:var(--font, "DM Sans Variable", sans-serif);line-height:1.6;text-decoration:none;}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent, #d9e6a3);outline-offset:5px;}

.ds-app-icon {
  object-fit: contain;
  flex-shrink: 0;
  display: block;
}
.ds-icon-fallback {
  background: #30362b;
  border-radius: 12px;
  display: grid;
  place-items: center;
  font: 600 22px var(--display, "Manrope Variable",sans-serif);
  color: var(--accent, #d9e6a3);
}
.ds-app-card {
  min-width: 0;
  padding: 29px 0 24px;
  border-bottom: 1px solid var(--line, #303236);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.ds-app-card-main {
  display: grid;
  grid-template-columns: 57px 1fr 18px;
  align-items: center;
  column-gap: 14px;
}
.ds-app-card .ds-app-icon {
  width: 54px;
  height: 54px;
}
.ds-app-card-name {
  min-width: 0;
}
.ds-app-card-name h3 {
  font-size: 18px;
  line-height: 1.3;
  letter-spacing: -0.025em;
}
.ds-app-card-name > span {
  font-size: 11px;
  color: var(--muted, #a7aaae);
  display: block;
  margin-top: 5px;
}
.ds-card-arrow {
  color: #b3bac4;
  transition: color 0.15s;
}
.ds-app-card-main:hover .ds-card-arrow {
  color: var(--accent, #d9e6a3);
}
.ds-app-card-main:hover h3 {
  color: var(--accent, #d9e6a3);
}
.ds-app-card-main > p {
  grid-column: 1/-1;
  font-size: 13px;
  color: #aeb4bd;
  line-height: 1.7;
  margin-top: 18px;
  min-height: 45px;
  max-width: 350px;
}
.ds-app-card-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-top: 20px;
}
.ds-tag {
  display: inline-flex;
  font-size: 10px;
  color: #bbc3cf;
  background: #24272c;
  border-radius: 4px;
  padding: 4px 8px;
  max-width: 55%;
  overflow-wrap: anywhere;
}
.ds-tag:hover {
  background: #353b44;
  color: var(--ink, #f2f2ef);
}
.ds-license-label {
  font-size: 10px;
  color: #a0a8b4;
  text-align: right;
  line-height: 1.4;
  max-width: 50%;
}
.ds-app-card{font-family:var(--font, "DM Sans Variable", sans-serif);line-height:1.6;color:var(--ink, #f2f2ef);max-width:400px}.ds-app-card a{text-decoration:none;color:inherit}.ds-app-card h3{margin:0;font-family:var(--display, "Manrope Variable",sans-serif);font-weight:600}.ds-app-card p{margin-bottom:0}.ds-app-card .ds-tag{color:#bbc3cf;}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent, #d9e6a3);outline-offset:5px;}
@media(prefers-reduced-motion:reduce){.ds-card-arrow{transition:none}}

.ds-top-links {
  display: flex;
  gap: 32px;
  font-size: 13px;
  align-items: center;
  margin-left: 50px;
}
.ds-top-links a {
  color: var(--muted, #a7aaae);
  display: flex;
  align-items: center;
  gap: 5px;
}
.ds-top-links a[aria-current='page'] {
  color: var(--ink, #f2f2ef);
}
.ds-top-links a:hover {
  color: var(--ink, #f2f2ef);
}
.ds-top-links{font-family:var(--font, "DM Sans Variable", sans-serif);line-height:1.6;}.ds-top-links a{text-decoration:none;color:var(--muted, #a7aaae)}.ds-top-links a:hover,.ds-top-links a[aria-current="page"]{color:var(--ink, #f2f2ef)}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent, #d9e6a3);outline-offset:5px;}
